+    await audit({ userId: user.id, entity: "FIGHTER", entityId: me.id, action: "PUBLIC_VIDEO_HIGHLIGHT", after: { highlightId: highlight.id, mediaId: media.id } }, tx);
+  }));
+  revalidatePath("/", "layout"); go(back, { aviso: "highlight_publico_anadido" });
+}

