// H: privacidad de avisos, referencia al vídeo original y cola única. Datos propios de pruebas; nunca producción.
import AxeBuilder from "@axe-core/playwright";
import { PrismaClient } from "@prisma/client";
import { B, rnd, browser, newUser, hacerAdmin, check, seen, terminarDiagnosticos } from "./ayudas.mjs";
const db = new PrismaClient();
const fan = await newUser("AvisoH");
const owner = await newUser("PeleadorH", "FIGHTER");
const [fanUser, ownerUser] = await Promise.all([db.user.findUniqueOrThrow({ where: { email: fan.email } }), db.user.findUniqueOrThrow({ where: { email: owner.email } })]);
const personal = await db.notification.create({ data: { userId: fanUser.id, kind: "CLASS_ANSWER", title: `Personal H ${rnd}`, href: "/mis-reservas" } });
const foreign = await db.notification.create({ data: { userId: ownerUser.id, kind: "CLASS_ANSWER", title: `Ajeno H ${rnd}`, href: "/mi-panel" } });
await db.notification.create({ data: { userId: fanUser.id, kind: "CLASS_ANSWER", title: `Caducado H ${rnd}`, href: "/mis-reservas", createdAt: new Date(Date.now() - 800 * 864e5) } });
await fan.p.goto(B + "/avisos");
check("solo se muestran avisos propios de los últimos doce meses", await seen(fan.p.getByText(personal.title, { exact: true })) && await fan.p.getByText(foreign.title, { exact: true }).count() === 0 && await fan.p.getByText(`Caducado H ${rnd}`, { exact: true }).count() === 0);
const exportResponse = await fan.p.request.get(B + "/mi-cuenta/datos");
const exported = await exportResponse.json();
check("la descarga contiene avisos propios vigentes, sin avisos ajenos ni caducados", exportResponse.ok() && exported.avisosDentroDeLaAplicacion.some((n) => n.titulo === personal.title) && exported.avisosDentroDeLaAplicacion.every((n) => n.titulo !== foreign.title && n.titulo !== `Caducado H ${rnd}`));
const card = fan.p.locator('article', { hasText: personal.title });
await card.locator('[name=notificationId]').evaluate((el, id) => { el.value = id; }, foreign.id);
await card.getByRole("button", { name: "Marcar como leído", exact: true }).click();
await fan.p.locator('.notice-bad').waitFor();
check("manipular el id no marca el aviso de otra cuenta", (await db.notification.findUniqueOrThrow({ where: { id: foreign.id } })).readAt === null);
await fan.p.goto(B + "/avisos");
await fan.p.locator('article', { hasText: personal.title }).getByRole("button", { name: "Marcar como leído", exact: true }).click();
await fan.p.locator('.notice-ok').waitFor();
check("el propio aviso queda leído", (await db.notification.findUniqueOrThrow({ where: { id: personal.id } })).readAt !== null);
const fighter = await db.fighter.create({ data: { userId: ownerUser.id, firstName: "Peleador", lastName: `Avisos${rnd}`, slug: `peleador-avisos-${rnd}`, level: "PRO", disciplines: { create: { discipline: "BOXEO", level: "PRO" } } } });
const opponent = await db.fighter.create({ data: { firstName: "Rival", lastName: `Avisos${rnd}`, slug: `rival-avisos-${rnd}`, level: "PRO", disciplines: { create: { discipline: "BOXEO", level: "PRO" } } } });
const event = await db.event.create({ data: { name: `Vídeo H ${rnd}`, slug: `video-h-${rnd}`, date: new Date(Date.now() - 5 * 864e5), status: "COMPLETED", discipline: "BOXEO", level: "PRO", venue: "Sala", city: "Madrid", province: "Madrid" } });
const bout = await db.bout.create({ data: { eventId: event.id, fighterAId: fighter.id, fighterBId: opponent.id, result: "A_WIN", verification: "VERIFIED" } });
const media = await db.mediaItem.create({ data: { uploaderId: fanUser.id, eventId: event.id, boutId: bout.id, kind: "VIDEO", caption: `Vídeo público H ${rnd}`, videoUrl: "https://example.com/video-prueba" } });
await owner.p.goto(B + "/mi-panel#videos");
await owner.p.getByRole("region", { name: "Vídeos de tus combates", exact: true }).getByRole("button", { name: "Añadir a mis highlights", exact: true }).click();
await owner.p.locator('.notice-ok').waitFor();
const copy = await db.highlight.findUniqueOrThrow({ where: { fighterId_sourceMediaId: { fighterId: fighter.id, sourceMediaId: media.id } } });
check("el highlight referencia el original y se avisa al autor", copy.videoKey === null && await db.notification.count({ where: { userId: fanUser.id, kind: "MEDIA_HIGHLIGHT" } }) === 1);
await owner.p.goto(B + `/peleadores/${fighter.slug}`);
check("la ficha publica el highlight", await seen(owner.p.getByText(media.caption, { exact: true }).first()));
await db.mediaItem.update({ where: { id: media.id }, data: { hiddenAt: new Date() } });
await owner.p.reload();
check("ocultar el original también oculta su highlight", await owner.p.getByText(media.caption, { exact: true }).count() === 0);
await db.mediaItem.delete({ where: { id: media.id } });
check("borrar el original retira la referencia en cascada", await db.highlight.count({ where: { id: copy.id } }) === 0);
const admin = await newUser("BandejaH"); hacerAdmin(admin.email);
await admin.p.goto(B + "/moderacion");
const queue = admin.p.getByRole("list", { name: "Bandeja de moderación ordenada por urgencia", exact: true });
const priorities = await queue.locator(':scope > li').evaluateAll((xs) => xs.map((x) => Number(x.dataset.prioridad)));
check("la bandeja es una lista sin pestañas y ordenada por urgencia", await admin.p.getByRole("tablist", { name: "Colas de moderación" }).count() === 0 && priorities.every((n, i) => i === 0 || n >= priorities[i - 1]));
check("las anclas antiguas siguen disponibles", await admin.p.locator('#avisos, #reclamaciones, #organizadores, #gimnasios, #senales, #combates, #revision').count() === 7);
const axe = await new AxeBuilder({ page: admin.p }).withTags(["wcag2a", "wcag2aa", "wcag21aa"]).analyze();
check("la bandeja pasa axe", axe.violations.length === 0);
await terminarDiagnosticos(); await db.$disconnect(); await browser.close();

